        node.outerHtmlHead(sb, 0, new Document("").outputSettings());
        Assert.assertEquals("Test", sb.toString());
    }

    @Test
    public void toStringTest() {
        TextNode node = new TextNode("Test");
        Assert.assertEquals("Test", node.toString());
    }

