    public void cloneTest() {
        TextNode node = new TextNode("Test");
        Assert.assertEquals(node, node.clone());
    }

    @Test
    public void createFromEncodedTest() {
        TextNode node = TextNode.createFromEncoded("Test", false);
        Assert.assertEquals("Test", node.getWholeText());
    }

    @Test
    public void normaliseWhitespaceTest() {
        String normalizedText = TextNode.normaliseWhitespace("  Test  Text  ");
        Assert.assertEquals(" Test Text ", normalizedText);
    }

    @Test
    public void stripLeadingWhitespaceTest() {
        String strippedText = TextNode.stripLeadingWhitespace(" Test Text");
        Assert.assertEquals("Test Text", strippedText);
    }

